index.content:
  .controls-wrapper {
    display: flex;
    flex-wrap: wrap;
    gap: 10px 14px;
    margin: 1rem 0 0.9rem;
    align-items: center;
    padding: 14px;
    background: var(--lightbg);
    border: 1px solid var(--lightgray);
    border-radius: 14px;
  }

  .toggle-group {
    display: flex;
    align-items: center;
    gap: 5px;
  }

  .toggle-label {
    font-size: 0.85rem;
    font-weight: bold;
    color: var(--darkgray);
    margin-right: 4px;
  }

  .week-btn, .group-btn, .ics-btn {
    background: var(--light);
    color: var(--darkgray);
    border: 1px solid var(--lightgray);
    min-height: 40px;
    padding: 8px 12px;
    border-radius: 9px;
    cursor: pointer;
    font-weight: 700;
    font-size: 0.88rem;
    line-height: 1.2;
    transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  }

  .week-btn:hover, .group-btn:hover, .ics-btn:hover {
    border-color: var(--secondary);
    color: var(--secondary);
  }

  .controls-wrapper button:focus-visible {
    outline: 2px solid var(--secondary);
    outline-offset: 2px;
  }

  .week-btn.active, .group-btn.active {
    background: var(--secondary);
    color: #ffffff;
    border-color: var(--secondary);
  }

  .ics-btn {
    color: var(--secondary);
    border-color: var(--secondary);
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .ics-btn:hover {
    background: var(--secondary);
    color: #ffffff;
  }

  .schedule-block {
    display: none;
  }

  /* Дни размещаются в сетке без горизонтальной прокрутки. */
  .schedule-block.active {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 215px), 1fr));
    gap: 12px;
    align-items: start;
  }

  .day-column {
    background-color: var(--lightbg);
    border: 1px solid var(--lightgray);
    border-radius: 12px;
    padding: 12px;
    display: flex;
    flex-direction: column;
    min-width: 0;
    box-sizing: border-box;
  }

  .day-header {
    font-weight: 700;
    font-size: 1rem;
    color: var(--dark);
    border-bottom: 1px solid var(--lightgray);
    padding-bottom: 9px;
    margin-bottom: 10px;
    text-align: left;
  }

  .lesson-card {
    background: color-mix(in srgb, var(--light) 65%, var(--lightgray));
    border-left: 3px solid var(--secondary);
    border-radius: 7px;
    padding: 10px;
    margin-bottom: 9px;
  }

  .lesson-card:last-child {
    margin-bottom: 0;
  }

  .lesson-time {
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--darkgray);
    margin-bottom: 5px;
  }

  .lesson-type {
    display: inline-block;
    font-size: 0.66rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    line-height: 1.5;
    padding: 0 6px;
    margin-left: 4px;
    border-radius: 999px;
    border: 1px solid var(--lightgray);
    color: var(--gray);
    vertical-align: middle;
  }

  /* ЛК: синий цвет темы */
  .lesson-type.lk {
    color: var(--secondary);
    background: rgba(123, 151, 170, 0.16);
    background: color-mix(in srgb, var(--secondary) 16%, transparent);
    border-color: rgba(123, 151, 170, 0.5);
    border-color: color-mix(in srgb, var(--secondary) 50%, transparent);
  }

  /* ПЗ: мягкий сиреневый */
  .lesson-type.pz {
    color: #6b5b95;
    background: rgba(155, 138, 196, 0.16);
    border-color: rgba(155, 138, 196, 0.5);
  }

  :root[saved-theme=&quot;dark&quot;] .lesson-type.pz { color: #b3a4dc; }

  .type-legend {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    font-size: 0.78rem;
    color: var(--darkgray);
    margin: -0.4rem 0 1rem;
  }

  .type-legend .lesson-type {
    margin-left: 0;
  }

  .lesson-name {
    font-size: 0.92rem;
    line-height: 1.35;
    font-weight: 600;
    color: var(--dark);
    margin-bottom: 6px;
  }

  .lesson-room {
    font-size: 0.75rem;
    display: inline-block;
    background-color: var(--lightgray);
    color: var(--darkgray);
    padding: 2px 6px;
    border-radius: 4px;
    font-family: monospace;
  }

  .no-lessons {
    font-size: 0.85rem;
    color: var(--darkgray);
    text-align: center;
    padding: 12px 0;
  }

  /* Блок контактов */
  .contact-box {
    margin-top: 2rem;
    padding: 12px 16px;
    background-color: var(--lightbg);
    border: 1px solid var(--lightgray);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
  }

  .contact-text {
    font-size: 0.8rem;
    color: var(--darkgray);
    line-height: 1.3;
  }

  .contact-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 12px;
    border-radius: 5px;
    font-size: 0.8rem;
    font-weight: 600;
    text-decoration: none !important;
    background-color: #2AABEE;
    color: #ffffff !important;
    transition: opacity 0.2s ease;
  }

  .contact-btn:hover {
    opacity: 0.85;
  }

  /* ===== Новое: преподаватель, сегодня, текущая пара, блок «Следующая пара» ===== */
  .lesson-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 5px 8px;
  }

  .lesson-teacher {
    font-size: 0.76rem;
    line-height: 1.3;
    color: var(--darkgray);
  }

  .day-column.today,
  .day-column.focus-next {
    border-color: var(--secondary);
    box-shadow: 0 0 0 1px var(--secondary);
  }

  .day-column.today .day-header::after,
  .day-column.focus-next .day-header::after {
    content: &quot;сегодня&quot;;
    display: inline-block;
    margin-left: 6px;
    padding: 0 7px;
    font-size: 0.6rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    line-height: 1.6;
    vertical-align: middle;
    border-radius: 999px;
    background: var(--secondary);
    color: #ffffff;
  }

  .day-column.focus-next .day-header::after {
    content: &quot;Завтра&quot;;
  }

  .lesson-card.now {
    background-color: rgba(123, 151, 170, 0.28);
    background-color: color-mix(in srgb, var(--secondary) 28%, transparent);
    box-shadow: 0 0 0 1px var(--secondary);
  }

  .lesson-card.now .lesson-time::after {
    content: &quot;идёт сейчас&quot;;
    display: inline-block;
    margin-left: 6px;
    padding: 0 7px;
    font-size: 0.6rem;
    font-weight: 700;
    line-height: 1.6;
    vertical-align: middle;
    border-radius: 999px;
    background: var(--tertiary);
    color: #ffffff;
  }

  .week-btn.cur::after {
    content: &quot; ●&quot;;
    font-size: 0.55em;
    vertical-align: middle;
  }

  .install-hint {
    font-size: 0.8rem;
    color: var(--darkgray);
    margin: -0.4rem 0 1rem;
  }

  .controls-wrapper .short {
    display: none;
  }

  /* Телефон: расписание должно быть видно сразу, без прокрутки */
  @media (max-width: 768px) {
    .content-meta {
      display: none !important;
    }

    h1.article-title {
      font-size: 1.5rem;
      margin: 0.3rem 0 0.2rem;
    }

    .controls-wrapper {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px 8px;
      margin: 0.6rem 0 0.8rem;
      padding: 12px;
    }

    .controls-wrapper .full {
      display: none;
    }

    .controls-wrapper .toggle-label {
      display: block;
      width: 100%;
      margin: 0 0 2px;
      font-size: 0.72rem;
    }

    .controls-wrapper .short {
      display: inline;
    }

    .controls-wrapper .toggle-group {
      flex-wrap: wrap;
      min-width: 0;
      gap: 6px;
    }

    .controls-wrapper .group-btn,
    .controls-wrapper .week-btn {
      flex: 1 1 0;
      min-width: 0;
      padding-inline: 4px;
    }

    .controls-wrapper .ics-btn {
      width: 100%;
    }

    .type-legend {
      display: none;
    }
  }

  /* Кнопка «Конспекты»: только на телефоне (на ПК проводник виден сбоку) */
  .notes-btn {
    display: none;
  }

  @media (max-width: 768px) {
    .notes-btn {
      display: inline-flex;
    }

    /* Мигающий ободок на кнопке бокового меню, пока её не нажали */
    .explorer-attn {
      border-radius: 6px;
      animation: explorer-pulse 1.8s ease-out infinite;
    }
  }

  @keyframes explorer-pulse {
    0%   { box-shadow: 0 0 0 0 rgba(123, 151, 170, 0.75); }
    70%  { box-shadow: 0 0 0 10px rgba(123, 151, 170, 0); }
    100% { box-shadow: 0 0 0 0 rgba(123, 151, 170, 0); }
  }

  @media (prefers-reduced-motion: reduce) {
    .explorer-attn { animation: none; box-shadow: 0 0 0 2px var(--secondary); }
  }




